"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { Activity, ArrowDownToLine, ArrowRight, Bell, Building2, CheckCircle2, ChevronDown, ChevronRight, ClipboardCheck, FileSpreadsheet, LayoutDashboard, LogOut, Plus, RefreshCw, Search, Send, Settings2, ShieldCheck, Trash2, UserRound, UsersRound } from "lucide-react";
import { buildIndicatorNodes, validateIndicatorHierarchy, type IndicatorChildDraft, type IndicatorGroupDraft } from "@/lib/indicator-hierarchy";

type Actor = { employeeNo: string; name: string; subsidiaryId: string; isSuperAdmin: boolean; adminSubsidiaryIds: string[] };
type Company = { id: string; name: string };
type Subsidiary = { id: string; companyId: string; name: string; status: string };
type Cycle = { id: string; companyId: string; name: string; status: string; startsAt?: string | null; endsAt?: string | null };
type Employee = { employeeNo: string; subsidiaryId: string; name: string; department: string; position: string; phone?: string; status: string };
type Assessment = { id: string; cycleId: string; employeeNo: string; employeeName?: string; subsidiaryId?: string; status: string; version: number; finalScore?: string | null };
type Node = { id: string; assessmentId: string; parentId: string | null; nodeCode?: string; name: string; description: string; scoringRule: string; maxScore: string; sortOrder: number; selfContent: string; adminFeedback?: string };
type Task = { id: string; assessmentId: string; cycleId: string; employeeNo: string; employeeName: string; status: string; version: number; totalScore: string | null; weight: string };
type Progress = { id: string; assessmentId: string; cycleId: string; employeeNo: string; scorerEmployeeNo: string; scorerName: string; status: string };
type TemplateColumn = { id: string; label: string; type: "TEXT" | "TEXTAREA" | "NUMBER" | "DATE"; required: boolean };
type TemplateRow = { id: string; label: string };
type Template = { id: string; name: string; layout: { columns: TemplateColumn[]; rows: TemplateRow[]; tree?: IndicatorGroupDraft[] }; nodes: { id: string; name: string; deductionRule: string; maxScore: string | null; sortOrder: number }[] };
type State = { actor: Actor; companies: Company[]; subsidiaries: Subsidiary[]; cycles: Cycle[]; mine: Assessment[]; myNodes: Node[]; myTasks: Task[]; taskNodes: Node[]; ownScoreItems: { taskId: string; nodeId: string; score: string; comment: string }[]; templates: Template[]; admin: { employees: Employee[]; assessments: Assessment[]; nodes: Node[]; assignments: { cycleId: string; employeeNo: string; scorerEmployeeNo: string; scorerName: string; weight: string }[]; progress: Progress[]; templateAssignments: { cycleId: string; employeeNo: string; templateId: string; templateName: string }[] } | null; super: { results: { cycleId: string; employeeNo: string; employeeName: string; subsidiaryName: string; status: string; finalScore: string | null; completedAt: string | null; scorerCount: number }[]; adminScopes: { adminEmployeeNo: string; subsidiaryId: string; employeeName: string; companyName: string; managedCompanyName: string; department: string; position: string }[] } | null };
type Role = "self" | "scorer" | "admin" | "super";
const statusLabel: Record<string, string> = { DRAFT: "待填报", RETURNED: "已退回", SUBMITTED: "已提交", SCORING: "打分中", COMPLETED: "已完成", PENDING: "待打分", ACTIVE: "进行中", STOPPED: "已停止", INACTIVE: "已停用" };
const apiBase = "/api/v1";
async function call(path: string, method = "GET", value?: unknown, idempotent = false) {
  const headers: Record<string, string> = {};
  if (!(value instanceof FormData) && value !== undefined) headers["Content-Type"] = "application/json";
  if (idempotent) headers["Idempotency-Key"] = crypto.randomUUID();
  const res = await fetch(`${apiBase}/${path}`, { method, headers, body: value === undefined ? undefined : value instanceof FormData ? value : JSON.stringify(value), credentials: "same-origin" });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error?.message ?? (Array.isArray(data.errors) ? data.errors.slice(0, 5).join("；") : "操作失败"));
  return data;
}
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="field"><span>{label}</span>{children}</label>; }
function Panel({ title, subtitle, children, actions }: { title: string; subtitle?: string; children: React.ReactNode; actions?: React.ReactNode }) { return <section className="panel"><div className="panel-head"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{actions}</div>{children}</section>; }
function Badge({ value }: { value: string }) { return <span className={`badge badge-${value.toLowerCase()}`}>{statusLabel[value] ?? value}</span>; }
function Empty({ text }: { text: string }) { return <div className="empty">{text}</div>; }

export default function Home() {
  const [state, setState] = useState<State | null>(null);
  const [loading, setLoading] = useState(true);
  const [role, setRole] = useState<Role>("self");
  const [requestedAdminCycleId, setRequestedAdminCycleId] = useState<string | undefined>();
  const [notice, setNotice] = useState("");
  const [busy, setBusy] = useState(false);
  const [changePassword, setChangePassword] = useState(false);
  const [notificationOpen, setNotificationOpen] = useState(false);
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const refresh = useCallback(async () => {
    try { const data = await call("state"); setState(data); }
    catch { setState(null); }
    finally { setLoading(false); }
  }, []);
  useEffect(() => {
    let live = true;
    call("state").then((data) => { if (live) setState(data); }).catch(() => { if (live) setState(null); }).finally(() => { if (live) setLoading(false); });
    return () => { live = false; };
  }, []);
  async function run(fn: () => Promise<unknown>, success = "操作已完成") {
    setBusy(true); setNotice("");
    try { await fn(); setNotice(success); await refresh(); }
    catch (error) { setNotice(error instanceof Error ? error.message : "操作失败"); }
    finally { setBusy(false); }
  }
  if (loading) return <div className="loading"><Activity size={28}/><span>正在载入考核工作台…</span></div>;
  if (!state) return <Login onLogin={refresh} />;
  const roles: { id: Role; label: string; icon: React.ReactNode }[] = [
    { id: "self", label: "我的指标", icon: <UserRound size={18}/> },
    { id: "scorer", label: "我的打分", icon: <ClipboardCheck size={18}/> },
    ...(state.admin ? [{ id: "admin" as Role, label: "管理员", icon: <LayoutDashboard size={18}/> }] : []),
    ...(state.actor.isSuperAdmin ? [{ id: "super" as Role, label: "超级管理员", icon: <ShieldCheck size={18}/> }] : []),
  ];
  const viewRole = roles.some((item) => item.id === role) ? role : "self";
  const returnedAssessments = state.mine.filter((assessment) => assessment.status === "RETURNED");
  return <div className="shell">
    <aside className="sidebar"><div className="brand"><div className="brand-mark"><Activity size={24}/></div><div><strong>衡标</strong><small>员工考核管理平台</small></div></div>
      <div className="nav-label">工作空间</div><nav>{roles.map((item) => <button key={item.id} className={`nav-item ${viewRole === item.id ? "active" : ""}`} onClick={() => setRole(item.id)}>{item.icon}<span>{item.label}</span><ArrowRight className="nav-arrow" size={16}/></button>)}</nav>
      <div className="sidebar-bottom"><div className="profile"><div className="avatar">{state.actor.name.slice(0, 1)}</div><div><b>{state.actor.name}</b><small>{state.actor.employeeNo}</small></div></div><button className="text-button" onClick={() => setChangePassword(true)}><Settings2 size={16}/>修改密码</button><button className="text-button" onClick={() => void run(async () => { await call("auth/logout", "POST"); setState(null); }, "已退出登录")}><LogOut size={16}/>退出登录</button></div>
    </aside>
    <main className="main"><header className="topbar"><div><span className="eyebrow">ASSESSMENT WORKSPACE</span><h1>{roles.find((item) => item.id === viewRole)?.label}</h1></div><div className="top-actions"><div className="notification-wrap"><button className="icon-button" title="通知" aria-label="通知" onClick={() => setNotificationOpen((open) => !open)}><Bell size={18}/>{returnedAssessments.length > 0 && <span className="notification-dot">{returnedAssessments.length}</span>}</button>{notificationOpen && <div className="notification-popover"><strong>待处理通知</strong>{returnedAssessments.length ? returnedAssessments.map((assessment) => <button key={assessment.id} type="button" onClick={() => { setRole("self"); setNotificationOpen(false); }}><b>指标已被退回</b><span>{state.cycles.find((cycle) => cycle.id === assessment.cycleId)?.name ?? "考核周期"}，请查看管理员意见并修改。</span></button>) : <span>暂无待处理通知</span>}</div>}</div><button className="icon-button" title="修改密码" onClick={() => setChangePassword(true)}><Settings2 size={18}/></button><button className="icon-button" title="退出登录" onClick={() => void run(async () => { await call("auth/logout", "POST"); setState(null); }, "已退出登录")}><LogOut size={18}/></button><button className="icon-button" title="刷新数据" onClick={() => void refresh()}><RefreshCw size={18}/></button></div></header>
      {notice && <div role="status" className="notice">{notice}<button onClick={() => setNotice("")}>×</button></div>}
      {changePassword && <div className="modal-backdrop"><form className="modal" onSubmit={(event) => { event.preventDefault(); void run(async () => { await call("auth/change-password", "POST", { currentPassword, newPassword }); setChangePassword(false); setState(null); }, "密码已修改，请重新登录"); }}><div className="panel-head"><div><h2>修改密码</h2><p>新密码至少 12 位，须包含字母和数字；修改后需重新登录。</p></div><button type="button" className="icon-button" onClick={() => setChangePassword(false)}>×</button></div><Field label="当前密码"><input type="password" autoComplete="current-password" value={currentPassword} onChange={(e) => setCurrentPassword(e.target.value)} required/></Field><Field label="新密码"><input type="password" autoComplete="new-password" minLength={12} value={newPassword} onChange={(e) => setNewPassword(e.target.value)} required/></Field><button className="primary wide" disabled={busy}>保存新密码</button></form></div>}
      <div className="content">{viewRole === "self" ? <SelfView state={state} run={run} busy={busy}/> : viewRole === "scorer" ? <ScorerView state={state} run={run} busy={busy}/> : viewRole === "admin" && state.admin ? <AdminView state={state} run={run} busy={busy} requestedCycleId={requestedAdminCycleId} onRequestedCycleHandled={() => setRequestedAdminCycleId(undefined)}/> : viewRole === "super" && state.super ? <SuperView state={state} run={run} busy={busy} onConfigureCycle={(cycleId) => { setRequestedAdminCycleId(cycleId); setRole("admin"); }}/> : null}</div>
    </main>
    <nav className="mobile-nav">{roles.map((item) => <button key={item.id} className={viewRole === item.id ? "active" : ""} onClick={() => setRole(item.id)}>{item.icon}<span>{item.label}</span></button>)}</nav>
  </div>;
}

function Login({ onLogin }: { onLogin: () => Promise<void> }) {
  const [employeeNo, setEmployeeNo] = useState(""); const [password, setPassword] = useState(""); const [error, setError] = useState(""); const [busy, setBusy] = useState(false);
  return <div className="login-page"><div className="login-art"><div className="brand large"><div className="brand-mark"><Activity size={28}/></div><div><strong>衡标</strong><small>员工考核管理平台</small></div></div><div><div className="art-kicker">清晰的指标 · 公平的评价</div><h1>让每一次考核<br/>有据可循。</h1><p>从指标填报到多人打分，在同一个工作台完成协作。</p></div><div className="art-footer">RUBRIC · ASSESSMENT PLATFORM</div></div><div className="login-side"><form className="login-card" onSubmit={async (event) => { event.preventDefault(); setBusy(true); setError(""); try { await call("auth/login", "POST", { employeeNo, password }); await onLogin(); } catch (err) { setError(err instanceof Error ? err.message : "登录失败"); } finally { setBusy(false); } }}><span className="eyebrow">WELCOME BACK</span><h2>登录工作台</h2><p>使用员工工号和密码继续。</p><Field label="工号"><input autoComplete="username" value={employeeNo} onChange={(event) => setEmployeeNo(event.target.value)} placeholder="请输入工号" required /></Field><Field label="密码"><input type="password" autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} placeholder="请输入密码" required /></Field>{error && <div className="form-error">{error}</div>}<button className="primary wide" disabled={busy}>{busy ? "登录中…" : "登录"}<ArrowRight size={18}/></button><div className="login-foot">首次使用请联系管理员获取初始账号。</div></form></div></div>;
}

function groupsFromNodes(nodes: Node[]): IndicatorGroupDraft[] {
  const root = nodes.find((node) => node.parentId === null);
  if (!root) return [];
  return nodes.filter((node) => node.parentId === root.id).map((group) => ({ name: group.name, description: group.description, scoringRule: group.scoringRule, maxScore: group.maxScore, selfContent: group.selfContent, children: nodes.filter((node) => node.parentId === group.id).map((child) => ({ name: child.name, description: child.description, scoringRule: child.scoringRule, maxScore: child.maxScore, selfContent: child.selfContent })) }));
}

function groupsFromTemplateTree(tree: Template["layout"]["tree"]): IndicatorGroupDraft[] {
  if (!Array.isArray(tree)) return [];
  return tree.map((group) => ({
    name: group.name ?? "", description: group.description ?? "", scoringRule: group.scoringRule ?? "", maxScore: group.maxScore === undefined || group.maxScore === null ? "" : String(group.maxScore),
    children: (group.children ?? []).map((child) => ({ name: child.name ?? "", description: child.description ?? "", scoringRule: child.scoringRule ?? "", maxScore: child.maxScore === undefined || child.maxScore === null ? "" : String(child.maxScore) })),
  }));
}

function IndicatorTreeEditor({ groups, onChange }: { groups: IndicatorGroupDraft[]; onChange: (groups: IndicatorGroupDraft[]) => void }) {
  const updateGroup = (index: number, update: Partial<IndicatorGroupDraft>) => onChange(groups.map((group, current) => current === index ? { ...group, ...update } : group));
  const updateChild = (groupIndex: number, childIndex: number, update: Partial<IndicatorChildDraft>) => onChange(groups.map((group, current) => current === groupIndex ? { ...group, children: group.children.map((child, childCurrent) => childCurrent === childIndex ? { ...child, ...update } : child) } : group));
  return <div className="indicator-builder"><div className="indicator-builder-head"><div><strong>树状考核指标</strong><small>一级指标可包含二级指标；一级合计必须为 100 分。</small></div><button className="text-button" type="button" onClick={() => onChange([...groups, { name: "", description: "", scoringRule: "", maxScore: "0", children: [] }])}><Plus size={16}/>添加一级指标</button></div>{groups.map((group, groupIndex) => <div className="indicator-group" key={groupIndex}><div className="indicator-group-title"><span>一级指标 {groupIndex + 1}</span><button className="remove" type="button" aria-label="删除一级指标" onClick={() => onChange(groups.filter((_, index) => index !== groupIndex))}>×</button></div><div className="indicator-group-grid"><Field label="指标名称"><input value={group.name} onChange={(event) => updateGroup(groupIndex, { name: event.target.value })}/></Field><Field label="考核内容"><textarea rows={2} value={group.description} onChange={(event) => updateGroup(groupIndex, { description: event.target.value })}/></Field><Field label="计分规则"><textarea rows={2} value={group.scoringRule} onChange={(event) => updateGroup(groupIndex, { scoringRule: event.target.value })}/></Field><Field label="分值"><input type="number" min="0" max="100" step="0.01" value={group.maxScore} onChange={(event) => updateGroup(groupIndex, { maxScore: event.target.value })}/></Field></div><div className="indicator-children"><div className="indicator-children-head"><span>二级指标（可选）</span><button className="link-button" type="button" onClick={() => updateGroup(groupIndex, { children: [...group.children, { name: "", description: "", scoringRule: "", maxScore: "0" }] })}><Plus size={14}/>添加二级指标</button></div>{group.children.map((child, childIndex) => <div className="indicator-child" key={childIndex}><span className="child-index">{groupIndex + 1}.{childIndex + 1}</span><Field label="指标名称"><input value={child.name} onChange={(event) => updateChild(groupIndex, childIndex, { name: event.target.value })}/></Field><Field label="考核内容"><input value={child.description} onChange={(event) => updateChild(groupIndex, childIndex, { description: event.target.value })}/></Field><Field label="计分规则"><input value={child.scoringRule} onChange={(event) => updateChild(groupIndex, childIndex, { scoringRule: event.target.value })}/></Field><Field label="分值"><input type="number" min="0" max="100" step="0.01" value={child.maxScore} onChange={(event) => updateChild(groupIndex, childIndex, { maxScore: event.target.value })}/></Field><button className="remove" type="button" aria-label="删除二级指标" onClick={() => updateGroup(groupIndex, { children: group.children.filter((_, index) => index !== childIndex) })}>×</button></div>)}</div></div>)}</div>;
}

function SelfView({ state, run, busy }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [selected, setSelected] = useState("");
  const assessments = state.mine.filter((a) => ["DRAFT", "ACTIVE"].includes(state.cycles.find((c) => c.id === a.cycleId)?.status ?? ""));
  const active = assessments.find((a) => a.id === selected) ?? assessments[0];
  const nodes = state.myNodes.filter((n) => n.assessmentId === active?.id);
  const [treeGroups, setTreeGroups] = useState<IndicatorGroupDraft[]>(() => groupsFromNodes(nodes));
  const leaves = nodes.filter((n) => !nodes.some((child) => child.parentId === n.id));
  const cycleStatus = state.cycles.find((cycle) => cycle.id === active?.cycleId)?.status;
  const indicatorDraftEditable = active?.status === "DRAFT" && cycleStatus === "DRAFT";
  const canSubmitSelf = active && ["DRAFT", "RETURNED"].includes(active.status) && cycleStatus === "ACTIVE";
  const completed = assessments.filter((a) => a.status === "COMPLETED").length;
  return <><div className="hero"><div><span className="eyebrow">EMPLOYEE SPACE</span><h2>你好，{state.actor.name}</h2><p>草稿周期仅用于保存指标；周期发布后才可提交管理员预审并进入评分。</p></div><div className="hero-stat"><strong>{completed}<span> / {assessments.length}</span></strong><small>已完成考核</small></div></div>
    <div className="tabs">{assessments.map((a) => <button key={a.id} className={a.id === active?.id ? "selected" : ""} onClick={() => { setSelected(a.id); setTreeGroups(groupsFromNodes(state.myNodes.filter((node) => node.assessmentId === a.id))); }}>{state.cycles.find((c) => c.id === a.cycleId)?.name ?? "考核周期"}</button>)}</div>
    {!active ? <Panel title="暂无指标草稿"><Empty text="管理员配置考核周期后，指标会显示在这里。"/></Panel> : <Panel title={cycleStatus === "DRAFT" ? "指标草稿" : "指标填报"} subtitle={cycleStatus === "DRAFT" ? "草稿周期仅保存指标；完整性将在发布周期时统一检查。" : "周期已发布，指标结构已冻结；确认后可提交管理员预审。"} actions={<Badge value={active.status}/>}> {/* 指标草稿与发布后只读视图共享同一容器。 */}
      {indicatorDraftEditable && <><IndicatorTreeEditor groups={treeGroups} onChange={setTreeGroups}/><div className={`indicator-validation ${validateIndicatorHierarchy(treeGroups).length ? "invalid" : "valid"}`}>{validateIndicatorHierarchy(treeGroups).length ? <span>当前可继续保存草稿；发布前需修正：{validateIndicatorHierarchy(treeGroups).join("；")}</span> : <span>树状指标与分值校验通过。</span>}</div><div className="panel-actions"><button className="primary" disabled={busy} onClick={() => void run(() => call(`my/assessments/${active.id}/tree`, "PATCH", { version: active.version, nodes: buildIndicatorNodes(treeGroups) }), "指标草稿已保存")}>保存指标草稿<CheckCircle2 size={16}/></button></div></>}
      {!indicatorDraftEditable && <div className="indicator-list">{nodes.map((node) => { const leaf = leaves.some((item) => item.id === node.id); return <div className={`indicator ${leaf ? "" : "parent"}`} key={node.id}><div className="indicator-title"><div><span className="node-code">{node.nodeCode}</span><strong>{node.name}</strong></div><span className="points">{node.maxScore} 分</span></div>{node.description && <p>{node.description}</p>}{node.scoringRule && <div className="scoring-rule">计分规则：{node.scoringRule}</div>}{node.adminFeedback && <div className="feedback">管理员参考意见：{node.adminFeedback}</div>}</div>; })}</div>}{canSubmitSelf && <div className="panel-actions"><button className="primary" disabled={busy} onClick={() => void run(() => call(`my/assessments/${active.id}/submit`, "POST", { version: active.version }, true), "已提交管理员预审")}>提交指标<Send size={16}/></button></div>}{active.status === "COMPLETED" && <div className="result-score">最终总分 <strong>{active.finalScore}</strong><span>/ 100</span></div>}</Panel>}</>;
}

function ScorerView({ state, run, busy }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [selected, setSelected] = useState(""); const [scores, setScores] = useState<Record<string, string>>({}); const [comments, setComments] = useState<Record<string, string>>({});
  const tasks = state.myTasks.filter((t) => state.cycles.find((c) => c.id === t.cycleId)?.status === "ACTIVE");
  const active = tasks.find((t) => t.id === selected) ?? tasks[0];
  const nodes = state.taskNodes.filter((n) => n.assessmentId === active?.assessmentId);
  const leaves = nodes.filter((n) => !nodes.some((child) => child.parentId === n.id));
  const existing = state.ownScoreItems.filter((item) => item.taskId === active?.id);
  const current = (id: string) => existing.find((item) => item.nodeId === id);
  const pending = tasks.filter((t) => t.status === "PENDING").length;
  const entered = leaves.filter((n) => (scores[n.id] ?? current(n.id)?.score ?? "") !== "").length;
  const runningTotal = leaves.reduce((total, n) => total + Number(scores[n.id] ?? current(n.id)?.score ?? 0), 0);
  const editable = active?.status === "PENDING";
  return <><div className="hero"><div><span className="eyebrow">SCORING SPACE</span><h2>我的打分任务</h2><p>只对已通过管理员审核的指标评分。评分无需审核；提交后即锁定，如需调整须走受控重开流程。</p></div><div className="hero-stat"><strong>{pending}</strong><small>待完成任务</small></div></div><div className="two-column"><Panel title="任务列表" subtitle={`共 ${tasks.length} 项打分任务`}><div className="task-list">{tasks.length ? tasks.map((task) => <button key={task.id} className={`task-row ${active?.id === task.id ? "selected" : ""}`} onClick={() => { setSelected(task.id); setScores({}); setComments({}); }}><div className="avatar small">{task.employeeName.slice(0, 1)}</div><div><strong>{task.employeeName}</strong><small>{task.employeeNo} · 权重 {Number(task.weight).toFixed(2)}%</small></div><Badge value={task.status}/></button>) : <Empty text="暂无打分任务。员工指标通过管理员审核后会出现在这里。"/>}</div></Panel><Panel title={active ? `为 ${active.employeeName} 打分` : "评分详情"} subtitle={active ? `本次评分在最终总分中的权重为 ${Number(active.weight).toFixed(2)}%。` : undefined} actions={active ? <Badge value={active.status}/> : undefined}>{!active ? <Empty text="选择左侧任务查看指标。"/> : <><div className="indicator-list">{nodes.map((node) => { const leaf = leaves.some((n) => n.id === node.id); return <div className={`indicator ${leaf ? "" : "parent"}`} key={node.id}><div className="indicator-title"><strong>{node.name}</strong><span className="points">满分 {node.maxScore}</span></div>{node.description && <p>{node.description}</p>}{node.scoringRule && <div className="scoring-rule">计分规则：{node.scoringRule}</div>}{node.selfContent && <div className="self-content">员工填报：{node.selfContent}</div>}{leaf && <div className="score-inputs"><Field label="得分"><input type="number" min="0" max={node.maxScore} step="0.01" disabled={!editable || busy} value={scores[node.id] ?? current(node.id)?.score ?? ""} onChange={(event) => setScores({ ...scores, [node.id]: event.target.value })}/></Field><Field label="评语（可选）"><input disabled={!editable || busy} value={comments[node.id] ?? current(node.id)?.comment ?? ""} onChange={(event) => setComments({ ...comments, [node.id]: event.target.value })} placeholder="填写评价说明"/></Field></div>}</div>; })}</div>{editable && <><div className="result-score">当前合计 <strong>{runningTotal.toFixed(2)}</strong><span>/ 100 · 已填 {entered}/{leaves.length} 项</span></div><div className="panel-actions"><button className="secondary" disabled={busy} onClick={() => void run(() => call(`scorer/tasks/${active.id}`, "PATCH", { version: active.version, items: leaves.filter((n) => (scores[n.id] ?? current(n.id)?.score ?? "") !== "").map((n) => ({ nodeId: n.id, score: Number(scores[n.id] ?? current(n.id)?.score), comment: comments[n.id] ?? current(n.id)?.comment ?? "" })) }), "评分已保存，可继续填写")}>保存评分</button><button className="primary" disabled={busy} onClick={() => void run(async () => { const result = await call(`scorer/tasks/${active.id}`, "PATCH", { version: active.version, items: leaves.filter((n) => (scores[n.id] ?? current(n.id)?.score ?? "") !== "").map((n) => ({ nodeId: n.id, score: Number(scores[n.id] ?? current(n.id)?.score), comment: comments[n.id] ?? current(n.id)?.comment ?? "" })) }); await call(`scorer/tasks/${active.id}/submit`, "POST", { version: result.version }, true); }, "评分已提交并锁定")}>提交评分<CheckCircle2 size={16}/></button></div></>}{active.status === "SUBMITTED" && <div className="result-score">本次打分 <strong>{active.totalScore}</strong><span>/ 100 · 权重 {Number(active.weight).toFixed(2)}% · 已锁定</span></div>}</>}</Panel></div></>;
}

function AdminView({ state, run, busy, requestedCycleId, onRequestedCycleHandled }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean; requestedCycleId?: string; onRequestedCycleHandled: () => void }) {
  const admin = state.admin!;
  const [cycleId, setCycleId] = useState(""); const [employeeNo, setEmployeeNo] = useState(""); const [scorerNos, setScorerNos] = useState("");
  const [indicatorGroups, setIndicatorGroups] = useState<IndicatorGroupDraft[]>([
    { name: "", description: "", scoringRule: "", maxScore: "100", children: [] },
  ]);
  const [reviewId, setReviewId] = useState(""); const [feedback, setFeedback] = useState<Record<string, string>>({});
  const [adminPage, setAdminPage] = useState<"overview" | "review" | "templates" | "configuration" | "people">("overview");
  const [newEmployee, setNewEmployee] = useState({ employeeNo: "", name: "", subsidiaryId: "", department: "", position: "", phone: "", initialPassword: "" });
  const cycles = state.cycles;
  const selectedCycle = cycles.find((c) => c.id === (requestedCycleId ?? cycleId)) ?? cycles[0];
  const currentAdminPage = requestedCycleId ? "configuration" : adminPage;
  const employees = admin.employees;
  const assessments = admin.assessments.filter((a) => a.cycleId === selectedCycle?.id);
  const target = assessments.find((a) => a.id === reviewId) ?? assessments.find((a) => a.status === "SUBMITTED");
  const nodes = admin.nodes.filter((n) => n.assessmentId === target?.id);
  const filled = assessments.filter((a) => !["DRAFT", "RETURNED"].includes(a.status)).length;
  const done = assessments.filter((a) => a.status === "COMPLETED").length;
  const progress = admin.progress.filter((p) => p.cycleId === selectedCycle?.id);
  const allDone = assessments.length > 0 && assessments.every((a) => a.status === "COMPLETED") && employees.length === assessments.length;
  const selectedEmployee = employees.find((employee) => employee.employeeNo === employeeNo) ?? { employeeNo: "", subsidiaryId: "", name: "", department: "", position: "", status: "INACTIVE" };
  const companyNameFor = (subsidiaryId: string) => state.subsidiaries.find((subsidiary) => subsidiary.id === subsidiaryId)?.name ?? "未分配公司";
  const indicatorErrors = validateIndicatorHierarchy(indicatorGroups);
  const updateGroup = (index: number, update: Partial<IndicatorGroupDraft>) => setIndicatorGroups((groups) => groups.map((group, current) => current === index ? { ...group, ...update } : group));
  const updateChild = (groupIndex: number, childIndex: number, update: Partial<IndicatorChildDraft>) => setIndicatorGroups((groups) => groups.map((group, current) => current === groupIndex ? { ...group, children: group.children.map((child, childCurrent) => childCurrent === childIndex ? { ...child, ...update } : child) } : group));
  async function importFile(kind: "employees" | "indicators" | "scorers", file: File) {
    const form = new FormData(); form.set("file", file);
    if (kind === "indicators") { form.set("cycleId", selectedCycle?.id ?? ""); form.set("employeeNo", employeeNo); form.set("scorers", JSON.stringify(scorerNos.split(/[，,\s]+/).filter(Boolean))); }
    if (kind === "scorers") form.set("cycleId", selectedCycle?.id ?? "");
    if (kind !== "indicators") {
      const preview = await call(`imports/${kind}`, "POST", form);
      if (!window.confirm(`校验通过 ${preview.valid} ${kind === "employees" ? "人" : "条打分关系"}，确认导入吗？`)) throw new Error("已取消导入");
      form.set("commit", "true");
    }
    return call(`imports/${kind}`, "POST", form);
  }
  return <><div className="section-intro"><div><span className="eyebrow">ADMIN WORKSPACE</span><h2>管理员工作台</h2><p>按工作事项进入页面，模板、人员匹配、审核和员工档案各自独立。</p></div><div className="select-wrap"><span>考核周期</span><select value={selectedCycle?.id ?? ""} onChange={(event) => { onRequestedCycleHandled(); setCycleId(event.target.value); }}>{cycles.map((c) => <option key={c.id} value={c.id}>{c.name} · {statusLabel[c.status] ?? c.status}</option>)}</select></div></div><nav className="workspace-tabs" aria-label="管理员功能页面">{([ ["overview", "概览"], ["review", "填报审核"], ["templates", "指标模板"], ["configuration", "人员配置"], ["people", "员工与导入"] ] as const).map(([id, label]) => <button key={id} type="button" className={currentAdminPage === id ? "active" : ""} onClick={() => { onRequestedCycleHandled(); setAdminPage(id); }}>{label}</button>)}</nav>
    {currentAdminPage === "overview" && <><div className="metrics"><Metric icon={<UsersRound size={21}/>} value={employees.length} label="总人数"/><Metric icon={<CheckCircle2 size={21}/>} value={filled} label="已填报"/><Metric icon={<Activity size={21}/>} value={Math.max(0, employees.length - filled)} label="未填报"/><Metric icon={<ShieldCheck size={21}/>} value={done} label="已完成打分"/></div>
    <div className="two-column"><Panel title="填报与审核" subtitle="可退回并逐项填写参考意见"><div className="table-scroll"><table><thead><tr><th>员工</th><th>使用模板</th><th>状态</th><th>操作</th></tr></thead><tbody>{employees.map((employee) => { const assessment = assessments.find((a) => a.employeeNo === employee.employeeNo); const template = admin.templateAssignments.find((item) => item.cycleId === selectedCycle?.id && item.employeeNo === employee.employeeNo); return <tr key={employee.employeeNo}><td><strong>{employee.name}</strong><small>{companyNameFor(employee.subsidiaryId)} · {employee.department || "未填写部门"} · {employee.position || "未填写职位"} · {employee.employeeNo}</small></td><td>{template ? <span className="template-chip">{template.templateName}</span> : <span className="muted">Excel 导入 / 未匹配</span>}</td><td>{assessment ? <Badge value={assessment.status}/> : <span className="muted">未配置</span>}</td><td>{assessment && ["DRAFT", "RETURNED"].includes(assessment.status) && <button className="link-button" disabled={busy} onClick={() => void run(() => call(`admin/assessments/${assessment.id}/remind`, "POST"), "已记录催办（暂不推送消息）")}>催办</button>}{assessment?.status === "SUBMITTED" && <button className="link-button" onClick={() => setReviewId(assessment.id)}>审核</button>}</td></tr>; })}</tbody></table></div></Panel>
      <Panel title="打分进度" subtitle="只显示完成状态，不显示得分或评语"><div className="table-scroll"><table><thead><tr><th>被考核人</th><th>打分人</th><th>状态</th></tr></thead><tbody>{progress.map((item) => <tr key={item.id}><td>{admin.employees.find((e) => e.employeeNo === item.employeeNo)?.name ?? item.employeeNo}</td><td>{item.scorerName}</td><td><Badge value={item.status}/></td></tr>)}</tbody></table>{!progress.length && <Empty text="指标通过审核后，打分进度会显示在这里。"/>}</div></Panel></div></>}
    {currentAdminPage === "review" && target && <Panel title={`审核 · ${target.employeeName}`} subtitle="审核指标结构与计分规则；管理员可逐项给出退回意见。"><div className="indicator-list">{nodes.map((n) => <div className="indicator" key={n.id}><div className="indicator-title"><strong>{n.name}</strong><span className="points">{n.maxScore} 分</span></div>{n.description && <p>考核内容：{n.description}</p>}{n.scoringRule && <div className="scoring-rule">计分规则：{n.scoringRule}</div>}<Field label="退回参考意见"><input value={feedback[n.id] ?? n.adminFeedback ?? ""} onChange={(event) => setFeedback({ ...feedback, [n.id]: event.target.value })} placeholder="可对每条指标提出修改意见"/></Field></div>)}</div><div className="panel-actions"><button className="secondary" disabled={busy} onClick={() => void run(() => call(`admin/assessments/${target.id}/return`, "POST", { version: target.version, feedback: nodes.map((n) => ({ nodeId: n.id, comment: feedback[n.id] ?? n.adminFeedback ?? "" })) }, true), "已退回员工修改")}>退回修改</button><button className="primary" disabled={busy} onClick={() => void run(() => call(`admin/assessments/${target.id}/approve`, "POST", { version: target.version }, true), "已审核通过，打分任务已生成")}>审核通过<CheckCircle2 size={16}/></button></div></Panel>}
    {false && <Panel title="树状指标配置" subtitle="按一级、二级指标逐层配置；一级合计为 100 分，二级合计须等于所属一级指标。">
      <div className="form-grid"><Field label="被考核人"><select value={employeeNo} onChange={(event) => setEmployeeNo(event.target.value)}><option value="">选择员工</option>{employees.map((employee) => <option key={employee.employeeNo} value={employee.employeeNo}>{employee.name} · {companyNameFor(employee.subsidiaryId)} · {employee.department || "未填写部门"} · {employee.position || "未填写职位"} · {employee.employeeNo}</option>)}</select></Field><Field label="打分人工号（多个用逗号分隔）"><input value={scorerNos} onChange={(event) => setScorerNos(event.target.value)} placeholder="例如 E1002,E1003"/></Field></div>
      {selectedEmployee && <div className="employee-context"><strong>{selectedEmployee.name}</strong><span>公司：{companyNameFor(selectedEmployee.subsidiaryId)}</span><span>部门：{selectedEmployee.department || "未填写"}</span><span>职位：{selectedEmployee.position || "未填写"}</span><span>工号：{selectedEmployee.employeeNo}</span></div>}
      <div className="indicator-builder"><div className="indicator-builder-head"><div><strong>考核指标</strong><small>每项可填写考核内容、计分规则和分值。</small></div><button className="text-button" type="button" onClick={() => setIndicatorGroups((groups) => [...groups, { name: "", description: "", scoringRule: "", maxScore: "0", children: [] }])}><Plus size={16}/>添加一级指标</button></div>
        {indicatorGroups.map((group, groupIndex) => <div className="indicator-group" key={groupIndex}><div className="indicator-group-title"><span>一级指标 {groupIndex + 1}</span><button className="remove" type="button" aria-label="删除一级指标" onClick={() => setIndicatorGroups((groups) => groups.filter((_, index) => index !== groupIndex))}>×</button></div><div className="indicator-group-grid"><Field label="指标名称"><input value={group.name} onChange={(event) => updateGroup(groupIndex, { name: event.target.value })} placeholder="例如：人力资源基础业务规范开展"/></Field><Field label="考核内容"><textarea rows={2} value={group.description} onChange={(event) => updateGroup(groupIndex, { description: event.target.value })} placeholder="说明该项考核的工作内容"/></Field><Field label="计分规则"><textarea rows={2} value={group.scoringRule} onChange={(event) => updateGroup(groupIndex, { scoringRule: event.target.value })} placeholder="例如：按时完成且材料齐全得满分"/></Field><Field label="分值"><input type="number" min="0" max="100" step="0.01" value={group.maxScore} onChange={(event) => updateGroup(groupIndex, { maxScore: event.target.value })}/></Field></div>
          <div className="indicator-children"><div className="indicator-children-head"><span>二级指标（可选）</span><button className="link-button" type="button" onClick={() => updateGroup(groupIndex, { children: [...group.children, { name: "", description: "", scoringRule: "", maxScore: "0" }] })}><Plus size={14}/>添加二级指标</button></div>{group.children.map((child, childIndex) => <div className="indicator-child" key={childIndex}><span className="child-index">{groupIndex + 1}.{childIndex + 1}</span><Field label="指标名称"><input value={child.name} onChange={(event) => updateChild(groupIndex, childIndex, { name: event.target.value })} placeholder="二级指标名称"/></Field><Field label="考核内容"><input value={child.description} onChange={(event) => updateChild(groupIndex, childIndex, { description: event.target.value })} placeholder="考核内容"/></Field><Field label="计分规则"><input value={child.scoringRule} onChange={(event) => updateChild(groupIndex, childIndex, { scoringRule: event.target.value })} placeholder="计分规则"/></Field><Field label="分值"><input type="number" min="0" max="100" step="0.01" value={child.maxScore} onChange={(event) => updateChild(groupIndex, childIndex, { maxScore: event.target.value })}/></Field><button className="remove" type="button" aria-label="删除二级指标" onClick={() => updateGroup(groupIndex, { children: group.children.filter((_, index) => index !== childIndex) })}>×</button></div>)}</div></div>)}</div>
      <div className={`indicator-validation ${indicatorErrors.length ? "invalid" : "valid"}`}>{indicatorErrors.length ? indicatorErrors.map((error) => <span key={error}>{error}</span>) : <span>一级指标合计 100 分；各级分值校验通过。</span>}</div>
      <div className="panel-actions wrap"><a className="secondary button-link" href={`${apiBase}/templates/indicators`}><ArrowDownToLine size={16}/>下载指标模板</a><label className="secondary upload"><FileSpreadsheet size={16}/>导入指标 Excel<input type="file" accept=".xlsx" onChange={(event) => { const file = event.target.files?.[0]; if (file) void run(() => importFile("indicators", file), "指标已导入"); event.target.value = ""; }}/></label><button className="primary" disabled={busy || !selectedCycle || !employeeNo || indicatorErrors.length > 0} onClick={() => void run(() => call("assessments", "POST", { cycleId: selectedCycle?.id, employeeNo, scorers: scorerNos.split(/[，,\s]+/).filter(Boolean), nodes: buildIndicatorNodes(indicatorGroups) }), "指标已设置")}>保存指标配置<CheckCircle2 size={16}/></button></div>
    </Panel>}
    {currentAdminPage === "templates" && <><TemplateManagementV3 state={state} run={run} busy={busy}/><TemplateTreePreset state={state} run={run} busy={busy}/></>}{currentAdminPage === "configuration" && <><div className="page-subtitle"><h3>人员配置</h3><p>仅用于将模板匹配给员工、配置打分人，并核对当前周期的人员配置结果。</p></div><TemplateOperationalPanels state={state} cycleId={selectedCycle?.id ?? ""} employees={employees} run={run} busy={busy}/><AdminConfigurationView admin={admin} employees={employees} cycleId={selectedCycle?.id ?? ""}/></>} {currentAdminPage === "people" && <><div className="two-column"><Panel title="新增员工" subtitle="员工以工号作为唯一标识；公司、部门、职位均为人员档案信息"><div className="stack"><Field label="工号"><input value={newEmployee.employeeNo} onChange={(e) => setNewEmployee({ ...newEmployee, employeeNo: e.target.value })}/></Field><Field label="姓名"><input value={newEmployee.name} onChange={(e) => setNewEmployee({ ...newEmployee, name: e.target.value })}/></Field><Field label="公司"><select value={newEmployee.subsidiaryId} onChange={(e) => setNewEmployee({ ...newEmployee, subsidiaryId: e.target.value })}><option value="">请选择</option>{state.subsidiaries.filter((s) => state.actor.isSuperAdmin || state.actor.adminSubsidiaryIds.includes(s.id)).map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}</select></Field><Field label="部门"><input value={newEmployee.department} onChange={(e) => setNewEmployee({ ...newEmployee, department: e.target.value })}/></Field><Field label="职位"><input value={newEmployee.position} onChange={(e) => setNewEmployee({ ...newEmployee, position: e.target.value })}/></Field><Field label="初始密码（至少 10 位）"><input type="password" value={newEmployee.initialPassword} onChange={(e) => setNewEmployee({ ...newEmployee, initialPassword: e.target.value })}/></Field><button className="primary" disabled={busy} onClick={() => void run(() => call("employees", "POST", newEmployee), "员工已创建")}>新增员工</button></div></Panel><Panel title="批量导入与导出" subtitle="员工模板包含公司、部门、职位；完成评分后导出最终总分。"><div className="import-actions"><a className="secondary button-link" href={`${apiBase}/templates/employees`}><ArrowDownToLine size={16}/>下载员工模板</a><label className="secondary upload"><FileSpreadsheet size={16}/>导入员工 Excel<input type="file" accept=".xlsx" onChange={(event) => { const file = event.target.files?.[0]; if (file) void run(() => importFile("employees", file), "员工已导入"); event.target.value = ""; }}/></label><a className="secondary button-link" href={`${apiBase}/templates/scorers`}><ArrowDownToLine size={16}/>下载打分关系模板</a><label className="secondary upload"><FileSpreadsheet size={16}/>导入打分关系<input type="file" accept=".xlsx" onChange={(event) => { const file = event.target.files?.[0]; if (file) void run(() => importFile("scorers", file), "打分关系已导入"); event.target.value = ""; }}/></label>{allDone ? <a className="primary button-link" href={`${apiBase}/export/final?cycleId=${selectedCycle?.id}`}><ArrowDownToLine size={16}/>导出最终总分</a> : <div className="export-hint">当前周期未全部完成，暂不可导出总分。</div>}</div></Panel></div><EmployeeProfileEditor state={state} employees={employees} run={run} busy={busy}/><OrganizationExplorer state={state} deleteTarget={() => undefined} readOnly/></>}{false && <><TemplateManagementV2 state={state} cycleId={selectedCycle?.id ?? ""} employees={employees} run={run} busy={busy}/><TemplateManagement state={state} cycleId={selectedCycle?.id ?? ""} employees={employees} run={run} busy={busy}/></>}</>;
}

function TemplateManagementV3({ state, run, busy }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const defaultColumns = (): TemplateColumn[] => [{ id: crypto.randomUUID(), label: "指标名称", type: "TEXT", required: true }, { id: crypto.randomUUID(), label: "扣分细则", type: "TEXTAREA", required: true }, { id: crypto.randomUUID(), label: "分值", type: "NUMBER", required: true }];
  const [editingId, setEditingId] = useState<string | null>(null); const [name, setName] = useState(""); const [columns, setColumns] = useState<TemplateColumn[]>(defaultColumns); const [rows, setRows] = useState<TemplateRow[]>([{ id: crypto.randomUUID(), label: "" }]); const [tree, setTree] = useState<IndicatorGroupDraft[]>([]);
  const selectTemplate = (template: Template) => { setEditingId(template.id); setName(template.name); setColumns(template.layout?.columns?.length ? template.layout.columns : defaultColumns()); setRows(template.layout?.rows ?? []); setTree(groupsFromTemplateTree(template.layout?.tree)); };
  const createTemplate = () => { setEditingId(null); setName(""); setColumns(defaultColumns()); setRows([{ id: crypto.randomUUID(), label: "" }]); setTree([]); };
  const save = () => run(() => call(editingId ? `templates/${editingId}` : "templates", editingId ? "PATCH" : "POST", { name, layout: { columns, rows, tree } }), editingId ? "模板已更新" : "模板已保存");
  return <><section className="template-workspace"><aside className="template-library"><div className="template-library-head"><div><span className="eyebrow">TEMPLATE LIBRARY</span><h2>指标模板</h2></div><button className="icon-button" aria-label="新建模板" title="新建模板" type="button" onClick={createTemplate}><Plus size={18}/></button></div><p>模板只保存填写结构，不保存任何指标内容。</p><div className="template-library-list">{state.templates.map((template) => <button type="button" key={template.id} className={`template-library-item ${editingId === template.id ? "selected" : ""}`} onClick={() => selectTemplate(template)}><strong>{template.name}</strong><small>{template.layout?.columns?.length ?? 0} 个字段 · {template.layout?.rows?.length ?? 0} 个预设行</small></button>)}{!state.templates.length && <Empty text="还没有模板，点击右上角新建。"/>}</div></aside><section className="template-editor" aria-label="模板编辑器"><div className="template-editor-head"><div><span className="eyebrow">{editingId ? "EDIT TEMPLATE" : "NEW TEMPLATE"}</span><h2>{editingId ? "编辑模板结构" : "新建模板结构"}</h2><p>定义员工填报时看到的字段列和空白预设行；这里不填写指标内容或分值。</p></div>{editingId && <span className="template-status">已保存，可继续编辑</span>}</div><Field label="模板名称"><input value={name} onChange={(event) => setName(event.target.value)} placeholder="例如：人事专员年度考核"/></Field><div className="template-section"><div className="template-section-head"><div><h3>填写字段</h3><p>字段是员工填报页面的列，可自定义名称、输入形式和必填性。</p></div><button className="secondary" type="button" onClick={() => setColumns([...columns, { id: crypto.randomUUID(), label: "", type: "TEXT", required: false }])}><Plus size={15}/>添加字段</button></div><div className="column-editor" role="list">{columns.map((column, index) => <div className="column-editor-row" role="listitem" key={column.id}><span className="column-index">{index + 1}</span><Field label="字段名称"><input value={column.label} onChange={(event) => setColumns(columns.map((item) => item.id === column.id ? { ...item, label: event.target.value } : item))} placeholder="例如：工作成果"/></Field><Field label="输入形式"><select value={column.type} onChange={(event) => setColumns(columns.map((item) => item.id === column.id ? { ...item, type: event.target.value as TemplateColumn["type"] } : item))}><option value="TEXT">单行文本</option><option value="TEXTAREA">多行文本</option><option value="NUMBER">数字</option><option value="DATE">日期</option></select></Field><label className="check-field"><input type="checkbox" checked={column.required} onChange={(event) => setColumns(columns.map((item) => item.id === column.id ? { ...item, required: event.target.checked } : item))}/>必填</label><button className="remove" aria-label={`删除字段 ${index + 1}`} type="button" disabled={columns.length === 1} onClick={() => setColumns(columns.filter((item) => item.id !== column.id))}>×</button></div>)}</div></div><div className="template-section"><div className="template-section-head"><div><h3>预设空行</h3><p>用于给员工一个起始填写数量；行标题可留空，不会作为指标内容保存。</p></div><button className="secondary" type="button" onClick={() => setRows([...rows, { id: crypto.randomUUID(), label: "" }])}><Plus size={15}/>添加预设行</button></div><div className="row-editor">{rows.map((row, index) => <div key={row.id} className="row-editor-item"><span>第 {index + 1} 行</span><input aria-label={`预设行 ${index + 1} 标题`} value={row.label} onChange={(event) => setRows(rows.map((item) => item.id === row.id ? { ...item, label: event.target.value } : item))} placeholder="行标题（可选，仅作填写提示）"/><button className="remove" aria-label={`删除预设行 ${index + 1}`} type="button" onClick={() => setRows(rows.filter((item) => item.id !== row.id))}>×</button></div>)}{!rows.length && <p className="muted">未设置预设行；员工将从空表格开始填写。</p>}</div></div><div className="template-preview"><strong>结构预览</strong><div className="template-preview-grid">{columns.map((column) => <span key={column.id}>{column.label || "未命名字段"}{column.required && <em>必填</em>}</span>)}</div></div><div className="panel-actions"><button className="secondary" type="button" onClick={createTemplate}>新建另一套模板</button><button className="primary" type="button" disabled={busy || !name.trim() || columns.some((column) => !column.label.trim())} onClick={() => void save()}>{editingId ? "保存修改" : "保存模板"}<CheckCircle2 size={16}/></button></div></section></section></>;
}

function TemplateTreePreset({ state, run, busy }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [templateId, setTemplateId] = useState("");
  const template = state.templates.find((item) => item.id === templateId);
  const [tree, setTree] = useState<IndicatorGroupDraft[]>([]);
  const choose = (id: string) => { setTemplateId(id); setTree(groupsFromTemplateTree(state.templates.find((item) => item.id === id)?.layout.tree)); };
  const saveTree = () => {
    if (!template) return;
    return run(() => call(`templates/${template.id}`, "PATCH", { name: template.name, layout: { columns: template.layout.columns, rows: template.layout.rows, tree } }), "模板树状指标预设已保存");
  };
  return <Panel title="模板树状指标预设" subtitle="选择已保存模板后，按一级、二级指标预设结构。字段可先留空；完整填写并分值合计为 100 时，会作为员工的初始指标树。"><Field label="选择要编辑的模板"><select value={templateId} onChange={(event) => choose(event.target.value)}><option value="">请选择模板</option>{state.templates.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field>{template ? <><IndicatorTreeEditor groups={tree} onChange={setTree}/><div className={`indicator-validation ${tree.length && validateIndicatorHierarchy(tree).length ? "invalid" : "valid"}`}>{!tree.length ? <span>尚未预设指标树；匹配后员工可从空白树开始填写。</span> : validateIndicatorHierarchy(tree).length ? <span>这是模板草稿，可继续留空；完整使用前请修正：{validateIndicatorHierarchy(tree).join("；")}</span> : <span>预设树完整，匹配员工时会自动复制该指标结构。</span>}</div><div className="panel-actions"><button className="primary" type="button" disabled={busy} onClick={() => void saveTree()}>保存树状预设<CheckCircle2 size={16}/></button></div></> : <Empty text="先在上方创建或选择一套模板，再配置它的树状指标预设。"/>}</Panel>;
}

function TemplateOperationalPanels({ state, cycleId, employees, run, busy }: { state: State; cycleId: string; employees: Employee[]; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [templateId, setTemplateId] = useState("");
  const [employeeSearch, setEmployeeSearch] = useState("");
  const [employeeNos, setEmployeeNos] = useState<string[]>([]);
  const [targetNo, setTargetNo] = useState("");
  const [scorerSearch, setScorerSearch] = useState("");
  const [scorerNos, setScorerNos] = useState<string[]>([]);
  const [weights, setWeights] = useState<Record<string, string>>({});
  const match = (person: Employee, query: string) => `${person.name} ${person.employeeNo}`.toLowerCase().includes(query.toLowerCase());
  const distribute = (ids: string[]) => {
    if (!ids.length) return {};
    const base = Math.floor(10_000 / ids.length); const remainder = 10_000 - base * ids.length;
    return Object.fromEntries(ids.map((id, index) => [id, ((base + (index < remainder ? 1 : 0)) / 100).toFixed(2)]));
  };
  const chooseTarget = (employeeNo: string) => {
    setTargetNo(employeeNo);
    const existing = state.admin?.assignments.filter((item) => item.cycleId === cycleId && item.employeeNo === employeeNo) ?? [];
    setScorerNos(existing.map((item) => item.scorerEmployeeNo));
    setWeights(Object.fromEntries(existing.map((item) => [item.scorerEmployeeNo, Number(item.weight).toFixed(2)])));
  };
  const toggleScorer = (employeeNo: string) => {
    const next = scorerNos.includes(employeeNo) ? scorerNos.filter((item) => item !== employeeNo) : [...scorerNos, employeeNo];
    setScorerNos(next); setWeights(distribute(next));
  };
  const totalWeight = scorerNos.reduce((total, employeeNo) => total + Number(weights[employeeNo] ?? 0), 0);
  const validWeightTotal = scorerNos.length > 0 && Math.abs(Math.round(totalWeight * 100) - 10_000) === 0 && scorerNos.every((employeeNo) => Number(weights[employeeNo]) > 0 && Number(weights[employeeNo]) <= 100 && /^\d+(\.\d{1,2})?$/.test(weights[employeeNo] ?? ""));
  return <div className="two-column"><Panel title="批量匹配员工" subtitle="选择已保存模板后，按姓名或工号筛选员工。"><Field label="模板"><select value={templateId} onChange={(event) => setTemplateId(event.target.value)}><option value="">请选择模板</option>{state.templates.map((template) => <option key={template.id} value={template.id}>{template.name}</option>)}</select></Field><Field label="搜索员工"><input value={employeeSearch} onChange={(event) => setEmployeeSearch(event.target.value)} placeholder="姓名或工号"/></Field><div className="person-picker">{employees.filter((person) => match(person, employeeSearch)).map((person) => <label key={person.employeeNo}><input type="checkbox" checked={employeeNos.includes(person.employeeNo)} onChange={() => setEmployeeNos(employeeNos.includes(person.employeeNo) ? employeeNos.filter((item) => item !== person.employeeNo) : [...employeeNos, person.employeeNo])}/><span><strong>{person.name}</strong> · {person.employeeNo}</span></label>)}</div><button className="primary" disabled={busy || !cycleId || !templateId || !employeeNos.length} onClick={() => void run(() => call("template-assignments", "POST", { cycleId, templateId, employeeNos }), "模板已批量匹配")}>匹配 {employeeNos.length} 名员工</button></Panel><Panel title="打分关系与权重" subtitle="多人打分的权重合计必须为 100.00%；草稿周期内可调整，发布后冻结。"><Field label="被打分人"><select value={targetNo} onChange={(event) => chooseTarget(event.target.value)}><option value="">请选择员工</option>{employees.map((person) => <option key={person.employeeNo} value={person.employeeNo}>{person.name} · {person.employeeNo}</option>)}</select></Field><Field label="搜索打分人"><input value={scorerSearch} onChange={(event) => setScorerSearch(event.target.value)} placeholder="姓名或工号"/></Field><div className="person-picker">{employees.filter((person) => person.employeeNo !== targetNo && match(person, scorerSearch)).map((person) => <label key={person.employeeNo}><input type="checkbox" checked={scorerNos.includes(person.employeeNo)} onChange={() => toggleScorer(person.employeeNo)}/><span><strong>{person.name}</strong> · {person.employeeNo}</span></label>)}</div>{scorerNos.length > 0 && <div className="weight-editor"><strong>权重分配</strong>{scorerNos.map((employeeNo) => { const employee = employees.find((person) => person.employeeNo === employeeNo); return <Field key={employeeNo} label={`${employee?.name ?? employeeNo} · ${employeeNo}`}><div className="inline-fields"><input type="number" min="0.01" max="100" step="0.01" value={weights[employeeNo] ?? ""} onChange={(event) => setWeights({ ...weights, [employeeNo]: event.target.value })}/><span>%</span></div></Field>; })}<div className={validWeightTotal ? "score-ok" : "score-warn"}>权重合计：{totalWeight.toFixed(2)} / 100.00</div></div>}<button className="primary" disabled={busy || !cycleId || !targetNo || !validWeightTotal} onClick={() => void run(() => call("scorer-assignments", "POST", { cycleId, employeeNo: targetNo, scorerAssignments: scorerNos.map((scorerEmployeeNo) => ({ scorerEmployeeNo, weight: Number(weights[scorerEmployeeNo]) })) }), "打分关系与权重已保存")}>保存打分关系</button></Panel></div>;
}

function AdminConfigurationView({ admin, employees, cycleId }: { admin: NonNullable<State["admin"]>; employees: Employee[]; cycleId: string }) {
  const rows = employees.map((employee) => ({ employee, template: admin.templateAssignments.find((item) => item.cycleId === cycleId && item.employeeNo === employee.employeeNo), scorers: admin.assignments.filter((item) => item.cycleId === cycleId && item.employeeNo === employee.employeeNo) }));
  return <Panel title="人员配置总览" subtitle="集中查看每位员工在当前周期使用的指标模板、打分人及权重；不展示任何得分细项。"><div className="table-scroll"><table><thead><tr><th>员工</th><th>使用模板</th><th>打分人及权重</th></tr></thead><tbody>{rows.map(({ employee, template, scorers }) => <tr key={employee.employeeNo}><td><strong>{employee.name}</strong><small>{employee.department || "未填写部门"} · {employee.position || "未填写职位"} · {employee.employeeNo}</small></td><td>{template ? <span className="template-chip">{template.templateName}</span> : <span className="muted">未匹配模板</span>}</td><td>{scorers.length ? scorers.map((item) => <span className="config-person" key={item.scorerEmployeeNo}>{item.scorerName} · {item.scorerEmployeeNo} · {Number(item.weight).toFixed(2)}%</span>) : <span className="muted">未配置打分人</span>}</td></tr>)}</tbody></table>{!rows.length && <Empty text="当前管理范围内暂无员工。"/>}</div></Panel>;
}

function EmployeeProfileEditor({ state, employees, run, busy }: { state: State; employees: Employee[]; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [selectedNo, setSelectedNo] = useState("");
  const employee = employees.find((item) => item.employeeNo === selectedNo);
  const [draft, setDraft] = useState({ subsidiaryId: "", department: "", position: "", phone: "", status: "ACTIVE" });
  const selectEmployee = (employeeNo: string) => { setSelectedNo(employeeNo); const next = employees.find((item) => item.employeeNo === employeeNo); if (next) setDraft({ subsidiaryId: next.subsidiaryId, department: next.department, position: next.position ?? "", phone: next.phone ?? "", status: next.status }); };
  const availableSubsidiaries = state.subsidiaries.filter((item) => state.actor.isSuperAdmin || state.actor.adminSubsidiaryIds.includes(item.id));
  return <Panel title="编辑员工信息" subtitle="工号和姓名为固定身份信息；可修改所属公司、部门、职位、手机号和在职状态。"><div className="form-grid"><Field label="选择员工"><select value={selectedNo} onChange={(event) => selectEmployee(event.target.value)}><option value="">请选择员工</option>{employees.map((item) => <option key={item.employeeNo} value={item.employeeNo}>{item.name} · {item.employeeNo}</option>)}</select></Field>{employee && <><Field label="工号"><input value={employee.employeeNo} disabled/></Field><Field label="姓名"><input value={employee.name} disabled/></Field><Field label="所属公司"><select value={draft.subsidiaryId} onChange={(event) => setDraft({ ...draft, subsidiaryId: event.target.value })}>{availableSubsidiaries.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></Field><Field label="部门"><input value={draft.department} onChange={(event) => setDraft({ ...draft, department: event.target.value })}/></Field><Field label="职位"><input value={draft.position} onChange={(event) => setDraft({ ...draft, position: event.target.value })}/></Field><Field label="手机号"><input value={draft.phone} onChange={(event) => setDraft({ ...draft, phone: event.target.value })}/></Field><Field label="在职状态"><select value={draft.status} onChange={(event) => setDraft({ ...draft, status: event.target.value })}><option value="ACTIVE">在职</option><option value="INACTIVE">已停用</option></select></Field></>}</div>{employee ? <div className="panel-actions"><button className="primary" disabled={busy || !draft.subsidiaryId || !draft.department.trim()} onClick={() => void run(() => call(`employees/${employee.employeeNo}`, "PATCH", draft), "员工信息已更新")}>保存员工信息<CheckCircle2 size={16}/></button></div> : <Empty text="选择一名员工后可编辑其档案信息。"/>}</Panel>;
}

function TemplateManagement({ state, cycleId, employees, run, busy }: { state: State; cycleId: string; employees: Employee[]; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [name, setName] = useState(""); const [min, setMin] = useState("1"); const [max, setMax] = useState("5"); const [rows, setRows] = useState([{ name: "", deductionRule: "", maxScore: "" }]); const [templateId, setTemplateId] = useState(""); const [selected, setSelected] = useState<string[]>([]); const [search, setSearch] = useState(""); const [scorerSearch, setScorerSearch] = useState(""); const [scorerTarget, setScorerTarget] = useState(""); const [scorerNos, setScorerNos] = useState<string[]>([]);
  const scoreTotal = rows.reduce((total, row) => total + Number(row.maxScore || 0), 0); const people = employees.filter((person) => `${person.name} ${person.employeeNo}`.toLowerCase().includes(search.toLowerCase())); const scorers = employees.filter((person) => `${person.name} ${person.employeeNo}`.toLowerCase().includes(scorerSearch.toLowerCase()));
  return <><Panel title="指标模板" subtitle="保存多套可复用模板。模板草稿可暂存；匹配员工前，名称、扣分细则、分值必须完整且总分为 100。"><div className="form-grid"><Field label="模板名称"><input value={name} onChange={(event) => setName(event.target.value)} placeholder="例如：人事专员年度考核"/></Field><Field label="最少 / 最多指标数"><div className="inline-fields"><input type="number" min="1" value={min} onChange={(event) => setMin(event.target.value)}/><input type="number" min="1" value={max} onChange={(event) => setMax(event.target.value)}/></div></Field></div><div className="template-rows">{rows.map((row, index) => <div className="template-row" key={index}><input placeholder="指标名称" value={row.name} onChange={(event) => setRows(rows.map((item, current) => current === index ? { ...item, name: event.target.value } : item))}/><input placeholder="扣分细则" value={row.deductionRule} onChange={(event) => setRows(rows.map((item, current) => current === index ? { ...item, deductionRule: event.target.value } : item))}/><input type="number" min="0" max="100" placeholder="分值" value={row.maxScore} onChange={(event) => setRows(rows.map((item, current) => current === index ? { ...item, maxScore: event.target.value } : item))}/><button className="remove" type="button" onClick={() => setRows(rows.filter((_, current) => current !== index))}>×</button></div>)}</div><div className="panel-actions start"><span className={scoreTotal === 100 ? "score-ok" : "score-warn"}>当前分值合计：{scoreTotal} / 100</span><button className="secondary" type="button" onClick={() => setRows([...rows, { name: "", deductionRule: "", maxScore: "" }])}><Plus size={16}/>添加指标</button><button className="primary" disabled={busy || !name.trim()} onClick={() => void run(() => call("templates", "POST", { name, minIndicators: Number(min), maxIndicators: Number(max), nodes: rows.map((row, index) => ({ ...row, maxScore: row.maxScore === "" ? null : Number(row.maxScore), sortOrder: index })) }), "模板已保存")}>保存模板</button></div></Panel><div className="two-column"><Panel title="批量匹配模板" subtitle="同一员工在同一周期仅能使用一套模板。"><Field label="选择模板"><select value={templateId} onChange={(event) => setTemplateId(event.target.value)}><option value="">请选择</option>{state.templates.map((template) => <option key={template.id} value={template.id}>{template.name} · {template.nodes.length} 项</option>)}</select></Field><Field label="搜索员工"><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="姓名或工号"/></Field><div className="person-picker">{people.map((person) => <label key={person.employeeNo}><input type="checkbox" checked={selected.includes(person.employeeNo)} onChange={() => setSelected(selected.includes(person.employeeNo) ? selected.filter((item) => item !== person.employeeNo) : [...selected, person.employeeNo])}/>{person.name} · {person.employeeNo}</label>)}</div><button className="primary" disabled={busy || !cycleId || !templateId || !selected.length} onClick={() => void run(() => call("template-assignments", "POST", { cycleId, templateId, employeeNos: selected }), "模板已批量匹配")}>匹配 {selected.length} 名员工</button></Panel><Panel title="配置打分关系" subtitle="独立配置；通过姓名或工号搜索并选择打分人。"><Field label="被打分人"><select value={scorerTarget} onChange={(event) => setScorerTarget(event.target.value)}><option value="">请选择</option>{employees.map((person) => <option key={person.employeeNo} value={person.employeeNo}>{person.name} · {person.employeeNo}</option>)}</select></Field><Field label="搜索打分人"><input value={scorerSearch} onChange={(event) => setScorerSearch(event.target.value)} placeholder="姓名或工号"/></Field><div className="person-picker">{scorers.filter((person) => person.employeeNo !== scorerTarget).map((person) => <label key={person.employeeNo}><input type="checkbox" checked={scorerNos.includes(person.employeeNo)} onChange={() => setScorerNos(scorerNos.includes(person.employeeNo) ? scorerNos.filter((item) => item !== person.employeeNo) : [...scorerNos, person.employeeNo])}/>{person.name} · {person.employeeNo}</label>)}</div><button className="primary" disabled={busy || !cycleId || !scorerTarget || !scorerNos.length} onClick={() => void run(() => call("imports/scorers", "POST", new FormData()), "")}>保存打分关系</button><p className="muted">请先使用下方的打分关系 Excel 导入；搜索选择式保存接口将在下一步接入。</p></Panel></div></>;
}

function TemplateManagementV2({ state, cycleId, employees, run, busy }: { state: State; cycleId: string; employees: Employee[]; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [name, setName] = useState(""); const [minimum, setMinimum] = useState("1"); const [maximum, setMaximum] = useState("5"); const [items, setItems] = useState([{ name: "", deductionRule: "", score: "" }]); const [templateId, setTemplateId] = useState(""); const [employeeSearch, setEmployeeSearch] = useState(""); const [employeeNos, setEmployeeNos] = useState<string[]>([]); const [targetNo, setTargetNo] = useState(""); const [scorerSearch, setScorerSearch] = useState(""); const [scorerNos, setScorerNos] = useState<string[]>([]);
  const match = (person: Employee, query: string) => `${person.name} ${person.employeeNo}`.toLowerCase().includes(query.toLowerCase()); const visibleEmployees = employees.filter((person) => match(person, employeeSearch)); const visibleScorers = employees.filter((person) => person.employeeNo !== targetNo && match(person, scorerSearch)); const total = items.reduce((sum, item) => sum + Number(item.score || 0), 0);
  const toggle = (value: string, values: string[], setValues: (next: string[]) => void) => setValues(values.includes(value) ? values.filter((item) => item !== value) : [...values, value]);
  return <><Panel title="指标模板" subtitle="模板可先保存为草稿；用于员工前必须填写指标名称、扣分细则、分值，且总分为 100。"><div className="form-grid"><Field label="模板名称"><input value={name} onChange={(event) => setName(event.target.value)} placeholder="例如：人事专员年度考核"/></Field><Field label="最少 / 最多指标数"><div className="inline-fields"><input type="number" min="1" value={minimum} onChange={(event) => setMinimum(event.target.value)}/><input type="number" min="1" value={maximum} onChange={(event) => setMaximum(event.target.value)}/></div></Field></div><div className="template-rows">{items.map((item, index) => <div className="template-row" key={index}><input placeholder="指标名称" value={item.name} onChange={(event) => setItems(items.map((row, rowIndex) => rowIndex === index ? { ...row, name: event.target.value } : row))}/><input placeholder="扣分细则" value={item.deductionRule} onChange={(event) => setItems(items.map((row, rowIndex) => rowIndex === index ? { ...row, deductionRule: event.target.value } : row))}/><input type="number" placeholder="分值" min="0" max="100" value={item.score} onChange={(event) => setItems(items.map((row, rowIndex) => rowIndex === index ? { ...row, score: event.target.value } : row))}/><button className="remove" type="button" onClick={() => setItems(items.filter((_, rowIndex) => rowIndex !== index))}>×</button></div>)}</div><div className="panel-actions start"><span className={total === 100 ? "score-ok" : "score-warn"}>分值合计 {total} / 100</span><button className="secondary" type="button" onClick={() => setItems([...items, { name: "", deductionRule: "", score: "" }])}><Plus size={16}/>添加指标</button><button className="primary" disabled={busy || !name.trim()} onClick={() => void run(() => call("templates", "POST", { name, minIndicators: Number(minimum), maxIndicators: Number(maximum), nodes: items.map((item, index) => ({ name: item.name, deductionRule: item.deductionRule, maxScore: item.score === "" ? null : Number(item.score), sortOrder: index })) }), "模板已保存")}>保存模板</button></div></Panel><div className="two-column"><Panel title="批量匹配员工" subtitle="一名员工在同一周期仅能适用一套模板。"><Field label="指标模板"><select value={templateId} onChange={(event) => setTemplateId(event.target.value)}><option value="">请选择模板</option>{state.templates.map((template) => <option key={template.id} value={template.id}>{template.name} · {template.nodes.length} 项</option>)}</select></Field><Field label="搜索员工"><input value={employeeSearch} onChange={(event) => setEmployeeSearch(event.target.value)} placeholder="输入姓名或工号"/></Field><div className="person-picker">{visibleEmployees.map((person) => <label key={person.employeeNo}><input type="checkbox" checked={employeeNos.includes(person.employeeNo)} onChange={() => toggle(person.employeeNo, employeeNos, setEmployeeNos)}/>{person.name} · {person.employeeNo}</label>)}</div><button className="primary" disabled={busy || !cycleId || !templateId || !employeeNos.length} onClick={() => void run(() => call("template-assignments", "POST", { cycleId, templateId, employeeNos }), "模板已批量匹配")}>匹配 {employeeNos.length} 名员工</button></Panel><Panel title="打分关系" subtitle="独立配置。搜索姓名或工号后，勾选一名或多名打分人。"><Field label="被打分人"><select value={targetNo} onChange={(event) => { setTargetNo(event.target.value); setScorerNos([]); }}><option value="">请选择员工</option>{employees.map((person) => <option key={person.employeeNo} value={person.employeeNo}>{person.name} · {person.employeeNo}</option>)}</select></Field><Field label="搜索打分人"><input value={scorerSearch} onChange={(event) => setScorerSearch(event.target.value)} placeholder="输入姓名或工号"/></Field><div className="person-picker">{visibleScorers.map((person) => <label key={person.employeeNo}><input type="checkbox" checked={scorerNos.includes(person.employeeNo)} onChange={() => toggle(person.employeeNo, scorerNos, setScorerNos)}/>{person.name} · {person.employeeNo}</label>)}</div><button className="primary" disabled={busy || !cycleId || !targetNo || !scorerNos.length} onClick={() => void run(() => call("scorer-assignments", "POST", { cycleId, employeeNo: targetNo, scorerEmployeeNos: scorerNos }), "打分关系已保存")}>保存打分关系</button></Panel></div></>;
}

function Metric({ icon, value, label }: { icon: React.ReactNode; value: number; label: string }) { return <div className="metric"><div className="metric-icon">{icon}</div><strong>{value}</strong><span>{label}</span></div>; }

type DeleteTarget = { entity: "companies" | "subsidiaries" | "employees" | "cycles"; id: string; label: string };

function SensitiveDeleteDialog({ target, onClose, run, busy }: { target: DeleteTarget | null; onClose: () => void; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [confirmation, setConfirmation] = useState("");
  if (!target) return null;
  const phrase = "我知道是敏感操作，确认删除";
  return <div className="modal-backdrop" role="presentation"><form className="modal danger-modal" onSubmit={(event) => { event.preventDefault(); void run(async () => { await call(`${target.entity}/${target.id}`, "DELETE", { confirmation }); onClose(); }, `已永久删除：${target.label}`); }}><div className="panel-head"><div><span className="danger-kicker">敏感操作</span><h2>永久删除“{target.label}”</h2><p>此操作会一并删除关联人员、指标、打分和授权记录，无法恢复。</p></div><button type="button" className="icon-button" onClick={onClose} aria-label="关闭删除确认">×</button></div><Field label={`请输入“${phrase}”以确认`}><input autoFocus value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></Field><div className="panel-actions"><button type="button" className="secondary" onClick={onClose}>取消</button><button className="danger-button" disabled={busy || confirmation !== phrase}>永久删除</button></div></form></div>;
}

function OrganizationExplorer({ state, deleteTarget, readOnly = false }: { state: State; deleteTarget: (target: DeleteTarget) => void; readOnly?: boolean }) {
  const [query, setQuery] = useState(""); const [expanded, setExpanded] = useState<Record<string, boolean>>({}); const [selected, setSelected] = useState<string>("");
  const normalized = query.trim().toLowerCase();
  const admin = state.admin;
  const companies = state.companies.filter((company) => !normalized || company.name.toLowerCase().includes(normalized) || state.subsidiaries.some((subsidiary) => subsidiary.companyId === company.id && (subsidiary.name.toLowerCase().includes(normalized) || admin?.employees.some((employee) => employee.subsidiaryId === subsidiary.id && `${employee.name} ${employee.department} ${employee.position} ${employee.employeeNo}`.toLowerCase().includes(normalized)))));
  const selectedSubsidiary = state.subsidiaries.find((subsidiary) => subsidiary.id === selected);
  const selectedCompany = state.companies.find((company) => company.id === selected);
  const visibleEmployees = admin?.employees.filter((employee) => selectedSubsidiary ? employee.subsidiaryId === selectedSubsidiary.id : selectedCompany ? state.subsidiaries.some((subsidiary) => subsidiary.companyId === selectedCompany.id && subsidiary.id === employee.subsidiaryId) : false) ?? [];
  return <Panel title="组织与人员目录" subtitle="按企业、子公司、人员逐层展开；可搜索后查看人员归属。"><Field label="搜索企业、子公司、姓名、部门、职位或工号"><div className="search-field"><Search size={16}/><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="输入关键词搜索"/></div></Field><div className="directory-layout"><div className="org-tree" role="tree">{companies.map((company) => { const subsidiaries = state.subsidiaries.filter((subsidiary) => subsidiary.companyId === company.id); const isOpen = expanded[company.id] || Boolean(normalized); return <div key={company.id} className="tree-company"><div className={`tree-row ${selected === company.id ? "selected" : ""}`}><button className="tree-toggle" type="button" aria-label={`${isOpen ? "收起" : "展开"}${company.name}`} onClick={() => setExpanded((value) => ({ ...value, [company.id]: !isOpen }))}>{isOpen ? <ChevronDown size={16}/> : <ChevronRight size={16}/>}</button><button type="button" className="tree-name" onClick={() => setSelected(company.id)}><Building2 size={15}/>{company.name}<small>{subsidiaries.length} 家子公司</small></button>{!readOnly && <button className="tree-delete" type="button" onClick={() => deleteTarget({ entity: "companies", id: company.id, label: company.name })} aria-label={`删除企业 ${company.name}`}><Trash2 size={15}/></button>}</div>{isOpen && subsidiaries.map((subsidiary) => <div key={subsidiary.id} className={`tree-row tree-child ${selected === subsidiary.id ? "selected" : ""}`}><span className="tree-indent"/><button type="button" className="tree-name" onClick={() => setSelected(subsidiary.id)}><Building2 size={14}/>{subsidiary.name}<small>{admin?.employees.filter((employee) => employee.subsidiaryId === subsidiary.id).length ?? 0} 人</small></button>{!readOnly && <button className="tree-delete" type="button" onClick={() => deleteTarget({ entity: "subsidiaries", id: subsidiary.id, label: subsidiary.name })} aria-label={`删除子公司 ${subsidiary.name}`}><Trash2 size={15}/></button>}</div>)}</div>; })}</div><div className="directory-detail">{selectedSubsidiary || selectedCompany ? <><h3>{selectedSubsidiary?.name ?? selectedCompany?.name}</h3><p>{selectedSubsidiary ? "子公司员工" : "企业全部员工"} · {visibleEmployees.length} 人</p><div className="directory-people">{visibleEmployees.map((employee) => <div key={employee.employeeNo} className="directory-person"><div><strong>{employee.name}</strong><small>{state.subsidiaries.find((subsidiary) => subsidiary.id === employee.subsidiaryId)?.name} · {employee.department || "未填写部门"} · {employee.position || "未填写职位"} · {employee.employeeNo}</small></div>{!readOnly && <button className="tree-delete" type="button" onClick={() => deleteTarget({ entity: "employees", id: employee.employeeNo, label: `${employee.name}（${employee.employeeNo}）` })} aria-label={`删除员工 ${employee.name}`}><Trash2 size={15}/></button>}</div>)}{!visibleEmployees.length && <Empty text="该范围暂无员工。"/>}</div></> : <Empty text="点击左侧企业或子公司，查看包含的员工。"/>}</div></div></Panel>;
}

function SystemManagement({ state, run, busy }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean }) {
  const [companyName, setCompanyName] = useState(""); const [subsidiaryName, setSubsidiaryName] = useState(""); const [companyId, setCompanyId] = useState(""); const [scopeEmployeeNo, setScopeEmployeeNo] = useState(""); const [scopeSubsidiaryId, setScopeSubsidiaryId] = useState(""); const [scopeQuery, setScopeQuery] = useState(""); const [deleteTarget, setDeleteTarget] = useState<DeleteTarget | null>(null);
  const employees = state.admin?.employees ?? [];
  const search = scopeQuery.trim().toLowerCase();
  const candidateEmployees = employees.filter((employee) => !search || `${employee.name} ${employee.department} ${employee.position} ${employee.employeeNo} ${state.subsidiaries.find((subsidiary) => subsidiary.id === employee.subsidiaryId)?.name ?? ""}`.toLowerCase().includes(search));
  const scopes = state.super?.adminScopes.filter((scope) => !search || `${scope.employeeName} ${scope.companyName} ${scope.managedCompanyName} ${scope.department} ${scope.position} ${scope.adminEmployeeNo}`.toLowerCase().includes(search)) ?? [];
  return <><div className="management-grid"><Panel title="新增企业" subtitle="创建一级企业"><div className="stack"><Field label="企业名称"><input value={companyName} onChange={(event) => setCompanyName(event.target.value)} placeholder="例如：中远海运（香港）有限公司"/></Field><button className="secondary" disabled={busy || !companyName.trim()} onClick={() => void run(() => call("companies", "POST", { name: companyName }), "企业已创建")}>新增企业</button></div></Panel><Panel title="新增子公司" subtitle="归属到指定一级企业"><div className="stack"><Field label="所属企业"><select value={companyId} onChange={(event) => setCompanyId(event.target.value)}><option value="">请选择企业</option>{state.companies.map((company) => <option key={company.id} value={company.id}>{company.name}</option>)}</select></Field><Field label="子公司名称"><input value={subsidiaryName} onChange={(event) => setSubsidiaryName(event.target.value)}/></Field><button className="secondary" disabled={busy || !companyId || !subsidiaryName.trim()} onClick={() => void run(() => call("subsidiaries", "POST", { companyId, name: subsidiaryName }), "子公司已创建")}>新增子公司</button></div></Panel></div><Panel title="管理员授权" subtitle="先搜索，再选择员工；下方仅展示符合搜索条件的管理员授权。"><div className="admin-search"><Field label="搜索人员或公司"><div className="search-field"><Search size={16}/><input value={scopeQuery} onChange={(event) => setScopeQuery(event.target.value)} placeholder="公司、姓名、部门、职位或工号"/></div></Field><Field label="管理员"><select value={scopeEmployeeNo} onChange={(event) => setScopeEmployeeNo(event.target.value)}><option value="">选择员工</option>{candidateEmployees.map((employee) => <option key={employee.employeeNo} value={employee.employeeNo}>{employee.name} · {state.subsidiaries.find((subsidiary) => subsidiary.id === employee.subsidiaryId)?.name ?? "未分配公司"} · {employee.department || "未填写部门"} · {employee.position || "未填写职位"} · {employee.employeeNo}</option>)}</select></Field><Field label="授权子公司"><select value={scopeSubsidiaryId} onChange={(event) => setScopeSubsidiaryId(event.target.value)}><option value="">请选择</option>{state.subsidiaries.map((subsidiary) => <option key={subsidiary.id} value={subsidiary.id}>{subsidiary.name}</option>)}</select></Field><button className="primary" disabled={busy || !scopeEmployeeNo || !scopeSubsidiaryId} onClick={() => void run(() => call("admin-scopes", "POST", { employeeNo: scopeEmployeeNo, subsidiaryId: scopeSubsidiaryId }), "授权已保存")}>授予管理员权限</button></div><div className="scope-list">{scopes.map((scope) => <div key={`${scope.adminEmployeeNo}-${scope.subsidiaryId}`}><ShieldCheck size={16}/><div className="scope-person"><strong>{scope.employeeName}</strong><small>{scope.companyName} · {scope.department || "未填写部门"} · {scope.position || "未填写职位"} · {scope.adminEmployeeNo}</small></div><ArrowRight size={14}/><span>管理：{scope.managedCompanyName}</span><button className="link-button" disabled={busy} onClick={() => void run(() => call("admin-scopes", "DELETE", { employeeNo: scope.adminEmployeeNo, subsidiaryId: scope.subsidiaryId }), "管理员授权已撤销")}>撤销</button></div>)}{!scopes.length && <Empty text="没有匹配的管理员授权记录。"/>}</div></Panel><OrganizationExplorer state={state} deleteTarget={setDeleteTarget}/><SensitiveDeleteDialog target={deleteTarget} onClose={() => setDeleteTarget(null)} run={run} busy={busy}/></>;
}

function SuperView({ state, run, busy, onConfigureCycle }: { state: State; run: (fn: () => Promise<unknown>, success?: string) => Promise<void>; busy: boolean; onConfigureCycle: (cycleId: string) => void }) {
  const [selectedCycle, setSelectedCycle] = useState("");
  const [superPage, setSuperPage] = useState<"overview" | "management" | "cycles" | "results">("overview");
  const [creatingCycle, setCreatingCycle] = useState(false);
  const [cycleForm, setCycleForm] = useState(() => { const initial = state.cycles[0]; return { name: initial?.name ?? "", startsAt: initial?.startsAt ? new Date(initial.startsAt).toISOString().slice(0, 16) : "", endsAt: initial?.endsAt ? new Date(initial.endsAt).toISOString().slice(0, 16) : "" }; });
  const cycles = state.cycles; const cycle = creatingCycle ? undefined : cycles.find((c) => c.id === selectedCycle) ?? cycles[0];
  const admin = state.admin!;
  const results = state.super!.results.filter((result) => result.cycleId === cycle?.id);
  const overview = useMemo(() => state.companies.map((company) => { const subsidiaries = state.subsidiaries.filter((s) => s.companyId === company.id); const employees = admin.employees.filter((e) => subsidiaries.some((s) => s.id === e.subsidiaryId)); const assessmentRows = admin.assessments.filter((a) => a.cycleId === cycle?.id && employees.some((employee) => employee.employeeNo === a.employeeNo)); return { company, employees: employees.length, filled: assessmentRows.filter((a) => !["DRAFT", "RETURNED"].includes(a.status)).length, completed: assessmentRows.filter((a) => a.status === "COMPLETED").length }; }), [state, admin, cycle?.id]);
  const cyclePayload = () => ({ name: cycleForm.name, startsAt: cycleForm.startsAt ? new Date(cycleForm.startsAt).toISOString() : null, endsAt: cycleForm.endsAt ? new Date(cycleForm.endsAt).toISOString() : null });
  const selectCycle = (id: string) => { const next = cycles.find((item) => item.id === id); setCreatingCycle(false); setSelectedCycle(id); if (next) setCycleForm({ name: next.name, startsAt: next.startsAt ? new Date(next.startsAt).toISOString().slice(0, 16) : "", endsAt: next.endsAt ? new Date(next.endsAt).toISOString().slice(0, 16) : "" }); };
  const beginCreate = () => { setCreatingCycle(true); setSelectedCycle(""); setCycleForm({ name: "", startsAt: "", endsAt: "" }); };
  return <><div className="section-intro"><div><span className="eyebrow">SYSTEM GOVERNANCE</span><h2>超级管理员工作台</h2><p>按治理事项分区管理组织、授权、周期和全局结果。</p></div></div><nav className="workspace-tabs" aria-label="超级管理员功能页面">{([ ["overview", "全局概览"], ["management", "组织与授权"], ["cycles", "考核周期"], ["results", "评分结果"] ] as const).map(([id, label]) => <button key={id} type="button" className={superPage === id ? "active" : ""} onClick={() => setSuperPage(id)}>{label}</button>)}</nav>
    {superPage === "overview" && <><div className="metrics"><Metric icon={<Building2 size={21}/>} value={state.companies.length} label="企业"/><Metric icon={<UsersRound size={21}/>} value={admin.employees.length} label="员工"/><Metric icon={<Settings2 size={21}/>} value={cycles.length} label="考核周期"/><Metric icon={<CheckCircle2 size={21}/>} value={admin.assessments.filter((a) => a.status === "COMPLETED").length} label="已完成考核"/></div><Panel title="企业进度" subtitle="跨企业汇总当前选定周期的填报和完成情况" actions={<select aria-label="选择考核周期" value={cycle?.id ?? ""} onChange={(event) => selectCycle(event.target.value)}>{cycles.map((item) => <option key={item.id} value={item.id}>{item.name} · {statusLabel[item.status] ?? item.status}</option>)}</select>}><div className="table-scroll"><table><thead><tr><th>企业</th><th>员工数</th><th>已填报</th><th>已完成</th></tr></thead><tbody>{overview.map((row) => <tr key={row.company.id}><td><strong>{row.company.name}</strong></td><td>{row.employees}</td><td>{row.filled}</td><td>{row.completed}</td></tr>)}</tbody></table></div></Panel></>}
    {superPage === "management" && <SystemManagement state={state} run={run} busy={busy}/>}
    {superPage === "cycles" && <><div className="two-column"><Panel title={creatingCycle ? "新建全员考核周期" : "编辑考核周期"} subtitle={creatingCycle ? "新周期初始为草稿，需完成人员配置后再发布。" : cycle?.status === "DRAFT" ? "草稿周期可编辑名称和时间范围。" : "进行中和已停止周期为历史记录，不可修改。"}><div className="stack"><Field label="考核周期"><input value={cycleForm.name} disabled={!creatingCycle && cycle?.status !== "DRAFT"} onChange={(event) => setCycleForm({ ...cycleForm, name: event.target.value })} placeholder="例如：2026 年度考核"/></Field><Field label="开始时间（可选）"><input type="datetime-local" value={cycleForm.startsAt} disabled={!creatingCycle && cycle?.status !== "DRAFT"} onChange={(event) => setCycleForm({ ...cycleForm, startsAt: event.target.value })}/></Field><Field label="结束时间（可选）"><input type="datetime-local" value={cycleForm.endsAt} disabled={!creatingCycle && cycle?.status !== "DRAFT"} onChange={(event) => setCycleForm({ ...cycleForm, endsAt: event.target.value })}/></Field><div className="panel-actions start"><button className="secondary" type="button" disabled={busy} onClick={beginCreate}>新建周期</button><button className="primary" disabled={busy || !cycleForm.name.trim() || (!creatingCycle && cycle?.status !== "DRAFT")} onClick={() => void run(() => creatingCycle ? call("cycles", "POST", cyclePayload()) : call(`cycles/${cycle?.id}`, "PATCH", cyclePayload()), creatingCycle ? "全员考核周期已创建" : "考核周期已更新")}>{creatingCycle ? "创建周期" : "保存修改"}<CheckCircle2 size={16}/></button></div></div></Panel><Panel title="周期状态与控制" subtitle="草稿周期必须先配置所有员工的指标草稿和打分关系，才可发布。"><div className="stack">{cycles.length ? <Field label="选择考核周期"><select value={cycle?.id ?? ""} onChange={(event) => selectCycle(event.target.value)}>{cycles.map((item) => <option key={item.id} value={item.id}>{item.name} · {statusLabel[item.status] ?? item.status}</option>)}</select></Field> : <Empty text="尚未创建考核周期。"/>}{cycle && <><div className="result-score">当前状态 <strong>{statusLabel[cycle.status] ?? cycle.status}</strong><span>{cycle.status === "STOPPED" ? "评分已锁定" : cycle.status === "DRAFT" ? "下一步：前往人员配置，为全部员工匹配模板和打分人" : "评分无需审核，停止前可修改"}</span></div><div className="panel-actions start">{cycle.status === "DRAFT" && <button className="secondary" disabled={busy} onClick={() => onConfigureCycle(cycle.id)}>前往人员配置<UsersRound size={16}/></button>}{cycle.status === "DRAFT" && <button className="primary" disabled={busy} onClick={() => void run(() => call(`cycles/${cycle.id}/publish`, "POST", {}, true), "考核周期已发布")}>发布周期<Send size={16}/></button>}{["DRAFT", "ACTIVE"].includes(cycle.status) && <button className="secondary" disabled={busy} onClick={() => { if (window.confirm("停止周期后，评分人将无法再修改或提交评分，且无法恢复。确认停止吗？")) void run(() => call(`cycles/${cycle.id}/stop`, "POST", {}, true), "考核周期已停止，评分已锁定"); }}>停止周期</button>}</div></>}</div></Panel></div><Panel title="全部考核周期" subtitle="选择周期后会切换上方的编辑与状态面板。"><div className="table-scroll"><table><thead><tr><th>周期</th><th>时间范围</th><th>状态</th><th>操作</th></tr></thead><tbody>{cycles.map((item) => <tr key={item.id} className={item.id === cycle?.id ? "selected-row" : ""}><td><strong>{item.name}</strong></td><td>{item.startsAt ? new Date(item.startsAt).toLocaleString() : "未设置"} — {item.endsAt ? new Date(item.endsAt).toLocaleString() : "未设置"}</td><td><Badge value={item.status}/></td><td><button className="link-button" type="button" onClick={() => selectCycle(item.id)}>{item.id === cycle?.id ? "正在查看" : item.status === "DRAFT" ? "查看 / 编辑" : "查看"}</button></td></tr>)}</tbody></table>{!cycles.length && <Empty text="尚未创建考核周期。"/>}</div></Panel></>}
    {superPage === "results" && <Panel title="最终总分与导出" subtitle="前端仅展示最终总分；多人打分时，最终总分为所有已提交评分总分的平均值。评分细则仅在 Excel 导出中提供。"><div className="panel-actions start"><select value={cycle?.id ?? ""} onChange={(event) => selectCycle(event.target.value)}>{cycles.map((item) => <option key={item.id} value={item.id}>{item.name} · {statusLabel[item.status] ?? item.status}</option>)}</select>{cycle && <><a className="primary button-link" href={`${apiBase}/export/final?cycleId=${cycle.id}`}><ArrowDownToLine size={16}/>导出最终总分</a><a className="secondary button-link" href={`${apiBase}/export/detail?cycleId=${cycle.id}`}><ArrowDownToLine size={16}/>导出评分细则</a></>}</div><div className="table-scroll"><table><thead><tr><th>员工</th><th>公司</th><th>打分人数</th><th>最终总分（平均分）</th><th>状态</th><th>完成时间</th></tr></thead><tbody>{results.map((result) => <tr key={result.employeeNo}><td><strong>{result.employeeName}</strong><small>{result.employeeNo}</small></td><td>{result.subsidiaryName}</td><td>{result.scorerCount}</td><td><strong>{result.finalScore === null ? "—" : Number(result.finalScore).toFixed(2)}</strong></td><td><Badge value={result.status}/></td><td>{result.completedAt ? new Date(result.completedAt).toLocaleString() : "—"}</td></tr>)}</tbody></table>{!results.length && <Empty text="当前周期暂无考核结果。"/>}</div></Panel>}</>;
}
